    def read_until(self, expected_result, timeout=None):
        """
        Read until a given string is encountered or until timeout seconds have passed.


        **Input parameters:**

        +------------------+------+----------------------------------+
        | Parameter name   | Man. | Description                      |
        +==================+======+==================================+
        | expected_result  | Yes  | expected BSC response            |
        +------------------+------+----------------------------------+
        | timeout          | No   | timeout for waiting for response |
        +------------------+------+----------------------------------+


        | **Return value:**
        | Text read up till and including the expected result. When no match is found, return whatever
        | is available instead, possibly the empty string.
        """
        if timeout:
            timeout = timestr_to_secs(timeout)
        output = self.cache.current_conn.read_until(expected_result, timeout)
        LOGGER.debug(output)
        return output

    def write(self, command):
        """
        Write given command to telnet socket.


        **Input parameters:**

        +----------------+------+-----------------+
        | Parameter name | Man. | Description     |
        +================+======+=================+
        | command        | Yes  | BSC MML command |
        +----------------+------+-----------------+
        """
        self.__clear_buffer(5)
        self.cache.current_conn.write(command + '\n\r')
        self.cache.current_conn.read_until(command)  #

    def read_output_from_mml_command(self, command, expected_result, timeout='30'):
        """
        Read output from given MML command until expected text is encountered.
        If bsc raises some error, this keyword fails with proper BSC exception.


        .. warning::
            Keyword is deprecated and is going to be removed in the next major release (4.0.0).
            Use ``Read Until`` and ``Write`` instead.


        **Input parameters:**

        +------------------+------+---------------------+
        | Parameter name   | Man. | Description         |
        +==================+======+=====================+
        | command          | Yes  | BSC MML command     |
        +------------------+------+---------------------+
        | expected_result  | Yes  | BSC expected output |
        +------------------+------+---------------------+
        | timeout          | No   | Read timeout        |
        +------------------+------+---------------------+


        **Examples:**

        .. code-block:: robotframework

            ${output}    Read Output From MML Command    Z?    _>    5


        | **Return value:**
        | BSC output
        """
        timeout = timestr_to_secs(timeout)
        start_time = time.time()
        while True:
            try:
                output = self._write_and_expect_result(command, expected_result)
                return output
            except Exception:
                if (start_time + timeout) < time.time():
                    raise
                continue

    def _write_and_expect_result(self, command, expected_result, timeout=None, *expected_exceptions, **additional_variables):
        if timeout:
            timeout = timestr_to_secs(timeout)
        with self._clear_buffer():
            self.cache.current_conn.write(command + '\n\r')
            output = self.cache.current_conn.read_until(expected_result, timeout)
            LOGGER.debug(output)
            try:
                self._check_output(expected_result, output)
                if 'additional_expected_result' in additional_variables.keys():
                    additional_output = self.cache.current_conn.read_until(additional_variables
                                                                           ['additional_expected_result'], 2)
                    LOGGER.debug(additional_output)
                return output
            except Exception as exc:
                if exc.__class__ in expected_exceptions:
                    return output
                raise

    @contextmanager
    def _clear_buffer(self):
        try:
            self.__clear_buffer(10)
            yield
        finally:
            self.cache.current_conn.read_very_eager()

    def __clear_buffer(self, timeout):
        """Read all from telnet buffer to clear it out."""
        start_time = time.time()
        while self.cache.current_conn.sock_avail() and (start_time + timeout) > time.time():
            self.cache.current_conn.read_very_eager()
        if self.cache.current_conn.sock_avail():
            LOGGER.debug("Buffer wasn't cleared.")

    def _check_output(self, expected_result, output):
        self._get_bsc_error_from_response(output)
        if expected_result not in output:
            raise NoMatchError('\'{}\' was not found in output: {}'.format(expected_result, output))

    def _get_bsc_error_from_response(self, bsc_response):
        error_pattern = r'/[\*]{3}(.*)[\*]{3}/'
        bsc_error = re.findall(error_pattern, bsc_response)
        if not bsc_error or 'WARNING' in bsc_error:
            self._check_if_bcf_exists(bsc_response)
            return bsc_response
        else:
            self.__raise_bsc_exception(bsc_error)

    @staticmethod
    def _check_if_bcf_exists(bsc_response):
        bcf_not_found_pattern = r'/\* BCF-(\d+?) NOT FOUND \*/'
        bcf_not_found_error = re.search(bcf_not_found_pattern, bsc_response)
        if bcf_not_found_error:
            raise BcfNotFound(bcf_not_found_error.group(1))

    @staticmethod
    def __raise_bsc_exception(bsc_error):
        exceptions = {'11229': IncorrectState,
                      '10824': LackOfResources,
                      '154': TimeLimitExceeded}
        dx_number, error_msg = get_bsc_dx_error(bsc_error)
        if dx_number:
            try:
                raise exceptions[dx_number](error_msg.lower())
            except KeyError:
                raise BscException('{}: {}'.format(dx_number, error_msg.lower()))
        else:
            raise BscException('{}'.format(error_msg.lower()))

    def get_bsc_time(self, time_format=None):
        """
        Return BSC time in a format specified by ``time_format``.

        Supported ``time_format`` values: ``date``, ``seconds``, ``hour``.
        1) if ``time_format`` is not provided, the keyword returns date and hour, e.g., 2016-08-25 10:33:38
        2) if ``time_format`` is set to ``date``, the keyword returns current BSC date, e.g., 2016-08-25
        3) if ``time_format`` is set to ``seconds``, the keyword returns the Unix time stamp (the number of seconds
        since January 1st, 1970), e.g., 1498813349
        4) if ``time_format`` is set to ``hour``, the keyword returns BSC time in format HH:MM:SS, e.g., 10:33:38


        **Input parameters:**

        +----------------+------+-----------------------+
        | Parameter name | Man. | Description           |
        +================+======+=======================+
        | time_format    | No   | requested time format |
        +----------------+------+-----------------------+


        **Examples:**

        .. code-block:: robotframework

             ${time}     Get Bsc Time
             ${date}     Get Bsc Time    date
             ${seconds}  Get Bsc Time    seconds
             ${hour}     Get Bsc Time    hour


        | **Return value:**
        | BSC time
        """
        is_valid_argument(time_format, ['date', 'seconds', 'hour', None])
        bsc_out = self._write_and_expect_result('ZDCD:;', 'COMMAND EXECUTED')
        bsc_date = re.search(r'((\d+-){2}\d+)\s*((\d+:){2}\d+)', bsc_out)
        if time_format == 'hour':
            return bsc_date.group(3)
        elif time_format == 'date':
            return bsc_date.group(1)
        elif not time_format:
            bsc_date = bsc_date.group(1) + ' ' + bsc_date.group(3)
            return bsc_date
        elif time_format == 'seconds':
            bsc_date = bsc_date.group(1) + ' ' + bsc_date.group(3)
            bsc_date = datetime.strptime(bsc_date, '%Y-%m-%d %H:%M:%S')
            return (bsc_date - datetime(1970, 1, 1)).total_seconds()

    def get_bsc_time_delta(self):
        """
        Return the difference between bsc time and current local time, in hours.
        """
        bsc_time = self.get_bsc_time()
        bsc_date = datetime.strptime(bsc_time, '%Y-%m-%d %H:%M:%S')
        return bsc_date.hour - datetime.now().hour

    def output_radio_network_configuration(self, bcf_id):
        """
        Return output from ``ZEEI:BCF=bcf_id``; command for given ``bcf_id``.


        **Input parameters:**

        +----------------+------+-------------+
        | Parameter name | Man. | Description |
        +================+======+=============+
        | bcf_id         | Yes  | BCF ID      |
        +----------------+------+-------------+


        | **Return value:**
        | radio network configuration output
        """
        rnc_out = self._write_and_expect_result('ZEEI:BCF={};'.format(bcf_id), 'COMMAND EXECUTED')
        return rnc_out

    def get_bts_parameters(self, bts_number, parameter_group, parameter_name=None):
        """
        Read BTS parameters for specified group from ``ZEQO:BTS=bts_number:parameter_group;`` command.

        Possible parameter groups:

        * ``IDE - BTS IDENTIFICATION PARAMETERS``
        * ``CEL - CELL ACCESS PARAMETERS``
        * ``RAD - RADIO LINK CONTROL DL PARAMETERS``
        * ``QUE - QUEUEING PARAMETERS``
        * ``CCH - CCH CONFIGURATION PARAMETERS``
        * ``INT - INTERFERENCE AVERAGING PARAMETERS``
        * ``MIS - MISCELLANEOUS PARAMETERS``
        * ``HOP - FREQUENCY HOPPING PARAMETERS``
        * ``BCC - BCCH FREQUENCY LIST USAGE PARAMETERS`
        * ``TRU - TRUNK RESERVATION PARAMETERS``
        * ``GPRS - GPRS PARAMETERS``
        * ``GPC - GPRS CONTROL PARAMETERS``
        * ``DAT - DATA SERVICE PARAMETERS``
        * ``AMR - AMR PARAMETERS``
        * ``ALL - ALL PARAMETERS``


        Fail with ``ValueError`` if invalid parameter group or invalid parameter name is entered.
        Fail with ``BscException`` if provided ``bts_number`` does not exist in bsc database.

        Parameter name can be defined with its short name displayed in BSC.


        **Input parameters:**

        +------------------+------+-------------+
        | Parameter name   | Man. | Description |
        +==================+======+=============+
        | bts_number       | Yes  | BTS ID      |
        +------------------+------+-------------+
        | parameter_group  | Yes  |             |
        +------------------+------+-------------+
        | parameter_name   | Yes  |             |
        +------------------+------+-------------+


        | **Return value:**
        | - if parameter name is specified, KW will return only its value (string format)
        | - if there's no specific parameter name to filter, KW will return dictionary with all parameters for specified
        | group in format ``{PARAMETER_LONG_NAME: PARAMETER_VALUE, ...}``.


        **Examples:**

        .. code-block:: robotframework

             ${ide_parameters}    Get BTS Parameters    2661   IDE
             ${lac_parameters}    Get BTS Parameters    bts_number=2661   parameter_group=IDE   parameter_name=LAC
        """
        parameter_groups = ['IDE', 'CEL', 'RAD', 'QUE', 'CCH', 'INT', 'MIS', 'HOP', 'BCC', 'TRU', 'GPRS', 'GPC',
                            'DAT', 'AMR', 'ALL']
        if parameter_group not in parameter_groups:
            raise ValueError('Unknown parameter group {}. Allowed values: {}'.format(parameter_group,
                                                                                     ', '.join(parameter_groups)))
        bts_parameters = self._write_and_expect_result('ZEQO:BTS={}:{};'.format(bts_number, parameter_group),
                                                       '<EQ_>', timeout=30)
        bts_parameters = bts_parameters.splitlines()
        parameters_data = {}
        parameters_shorts = {}
        for line in bts_parameters:
            param_data = re.search(r'^([A-Z\s]*)\.*\((.*)\)\.*\s(.*)$', line)
            if param_data:
                param_name, param_short, param_value = param_data.group(1).strip(), param_data.group(2), \
                                                       param_data.group(3).strip()  # noqa: E126
                if parameter_name == param_name or parameter_name == param_short:
                    return param_value
                parameters_shorts[param_short] = param_value
                parameters_data[param_name] = param_value
        if parameter_name and (parameter_name not in parameters_data and parameter_name not in parameters_shorts):
            raise ValueError('Specified parameter name {} does not exist in BSC for group {}'.format(parameter_name,
                                                                                                     parameter_group))
        return parameters_data

    def get_bcf_status(self, bcf_id):
        """
        Read bcf operational and administrative states from output radio network
        configuration command (``ZEEI:BCF=bcf_id;``).


        **Input parameters:**

        +------------------+------+---------------------+
        | Parameter name   | Man. | Description         |
        +==================+======+=====================+
        | bcf_id           | Yes  | BCF ID              |
        +------------------+------+---------------------+


        | **Return value:**
        | list with administrative and operational state values respectively

        """
        rnc_out = self.output_radio_network_configuration(bcf_id)
        bcf_def_line = re.search(r'(BCF-\d+)\s+.*?\s.*?\s+?[UL]\s(WO|BL-.*?)\s', rnc_out)
        states = re.findall(r'(U|L|WO|BL-.*?)\s+', bcf_def_line.group(0))
        LOGGER.info('{} administrativeState: {}, '
                    'operationalState: {}'.format(bcf_def_line.group(1), states[0], states[1]))
        return states

    def get_sectors_state(self, bcf_id, state):
        """
        Get operational or administrative state for all sectors of a given BCF.


        **Input parameters:**

        +------------------+------+---------------------+
        | Parameter name   | Man. | Description         |
        +==================+======+=====================+
        | bcf_id           | Yes  | BCF ID              |
        +------------------+------+---------------------+
        | state            | Yes  | state to get        |
        +------------------+------+---------------------+


        | **Return value:**
        | list of tuples with sectors IDs and states


        **Examples:**

        .. code-block:: robotframework

             ${operational}       Get Sectors State    15    operational
             ${administrative}    Get Sectors State    15    administrative
        """
        state_regex = {'operational': r'[^S](BTS-\d+)\s+[\w+]\s+([A-Z-]+)',
                       'administrative': r'[^S](BTS-\d+)\s+([A-Z-]+)'}
        rnc_out = self.output_radio_network_configuration(bcf_id)
        state = state.lower()
        sectors_states = ''
        if is_valid_argument(state, ['operational', 'administrative']):
            pattern = state_regex[state]
            sectors_states = re.findall(pattern, rnc_out)
        log_states(sectors_states, state)
        return sectors_states

    def get_sectors_status(self, bcf_id):
        """
        Get both operational and administrative states for all sectors of a given BCF.


        **Input parameters:**

        +------------------+------+---------------------+
        | Parameter name   | Man. | Description         |
        +==================+======+=====================+
        | bcf_id           | Yes  | BCF ID              |
        +------------------+------+---------------------+


        | **Return value:**
        | list of tuples with sectors IDs and administrative and operational states.
        """
        rnc_out = self.output_radio_network_configuration(bcf_id)
        states = re.findall(r'\s(BTS-\d+)\s+([\w-]+)\s+([\w-]+)', rnc_out)
        log_status(states)
        return states

    def get_trxs_state(self, bcf_id, state):
        """
        Get operational or administrative state for all TRXs of a given BCF.


        **Input parameters:**

        +------------------+------+---------------------+
        | Parameter name   | Man. | Description         |
        +==================+======+=====================+
        | bcf_id           | Yes  | BCF ID              |
        +------------------+------+---------------------+
        | state            | Yes  | state to get        |
        +------------------+------+---------------------+


        | **Return value:**
        | list of tuples with trxs IDs and states


        **Examples:**

        .. code-block:: robotframework

             ${operational}     Get Trxs State    15    operational
             ${administrative}  Get Trxs State    15    administrative
        """
        state_regex = {'operational': r'(TRX-\d+)\s+[\w+]\s+([A-Z-]+)', 'administrative': r'(TRX-\d+)\s+([A-Z-]+)'}
        rnc_out = self.output_radio_network_configuration(bcf_id)
        state = state.lower()
        trx_states = []
        if is_valid_argument(state, ['operational', 'administrative']):
            pattern = state_regex[state]
            trx_states = re.findall(pattern, rnc_out)
