    def get_trxs_ids(self, bcf_id, alias=True):
        """
        Get trxs IDs from output radio network configuration command.


        **Input parameters:**

        +------------------+------+---------------------------------------+
        | Parameter name   | Man. | Description                           |
        +==================+======+=======================================+
        | bcf_id           | Yes  | BCF ID                                |
        +------------------+------+---------------------------------------+
        | alias            | No   | boolean flag if TRX alias is required |
        +------------------+------+---------------------------------------+


        | **Return value:**
        | list of ids with or without TRX alias. Default option is with an alias.
        | Example with alias ``['TRX-001', 'TRX-002', 'TRX-003', 'TRX-004', 'TRX-005', 'TRX-006']``
        | Example without alias  ``['1', '2', '3', '4', '5', '6']``


        **Examples:**

        .. code-block:: robotframework

             ${trxs with alias}     Get Trxs Ids    15
             ${trxs without alias}  Get Trxs Ids    15    alias=${False}
        """
        rnc_out = self.output_radio_network_configuration(bcf_id)
        if alias:
            trxs_list = re.findall(r'\bTRX\b-\d+', rnc_out)
        else:
            trxs_list = re.findall(r'\bTRX\b-0*(\d+)', rnc_out)
        trxs_list = [six.text_type(trx) for trx in trxs_list]
        return trxs_list

    def get_transceiver_parameters(self, bts_id, trx_id):
        """
        Get transceiver parameters by executing command ``ZERO:BTS=bts_id,TRX=trx_id;``


        **Input parameters:**

        +------------------+------+---------------------------------------+
        | Parameter name   | Man. | Description                           |
        +==================+======+=======================================+
        | bts_id           | Yes  | BTS ID                                |
        +------------------+------+---------------------------------------+
        | trx_id           | Yes  | trx identification (string)           |
        +------------------+------+---------------------------------------+


        | **Return value:**
        | ZERO command output (string)


        **Examples:**

        .. code-block:: robotframework

            ${params}=    Get Transceiver Parameters    666    6

        """
        output = self._write_and_expect_result('ZERO:BTS={bts_id},TRX={trx_id};'.format(bts_id=bts_id, trx_id=trx_id), 'COMMAND EXECUTED')
        return output

    def get_transceiver_data(self, bts_id, trx_id):
        """
         Get transceiver parameters (``ZERO:BTS=bts_id,TRX=trx_id;``) parsed into a dictionary


        | **Author:** andrzej.cichon@nokia.com
        | **Maintainer:** andrzej.cichon@nokia.com
        | **Released in:** 3.9.0


         **Input parameters:**

         +------------------+------+---------------------------------------+
         | Parameter name   | Man. | Description                           |
         +==================+======+=======================================+
         | bts_id           | Yes  | BTS ID                                |
         +------------------+------+---------------------------------------+
         | trx_id           | Yes  | trx identification (string)           |
         +------------------+------+---------------------------------------+


         | **Return value:**
         | dictionary


         **Examples:**

         .. code-block:: robotframework

             ${data}=    Get Transceiver Data    666    6

             =>
             {'ADM.STATE': ('UNLOCKED',
                            'UNLOCKED',
                            'UNLOCKED',
                            'UNLOCKED',
                            'UNLOCKED',
                            'UNLOCKED',
                            'UNLOCKED',
                            'UNLOCKED'),
             'CH.STATUS': (None, None, 'ID', 'ID', 'ID', 'ID', 'ID', 'GP'),
             'I.LEV': ('-', '-', '0', '0', '0', '0', '0', '0'),
             'OP.STATE': ('WO', 'WO', 'WO', 'WO', 'WO', 'WO', 'WO', 'WO'),
             'PCM-TSL': ('-', '-', '-', '-', '-', '-', '-', '-'),
             'RTSL': ('0', '1', '2', '3', '4', '5', '6', '7'),
             'SUB_TSL': ('-', '-', '-', '-', '-', '-', '-', '-'),
             'TYPE': ('MBCCH',
                      'SDCCH',
                      'TCHF',
                      'TCHF',
                      'TCHF',
                      'TCHF',
                      'TCHF',
                      'TCHF')}
         """
        transceiver_parameters = self.get_transceiver_parameters(bts_id, trx_id)
        table = self._get_transceiver_data_table(transceiver_parameters)
        table = {column[0]: column[1:] for column in izip_longest(*table)}
        return table

    def get_trx_timeslot_status(self, bts_id, trx_id):
        """
        Get CH.STATUS column values from get transceiver parameters command


        **Input parameters:**

        +------------------+------+---------------------------------------+
        | Parameter name   | Man. | Description                           |
        +==================+======+=======================================+
        | bts_id           | Yes  | BTS ID                                |
        +------------------+------+---------------------------------------+
        | trx_id           | Yes  | trx identification (string)           |
        +------------------+------+---------------------------------------+


        | **Return value:**
        | CH.STATUS column values (tuple), raise ``BscException`` in case CH.STATUS column is empty

        """
        table = self.get_transceiver_data(bts_id, trx_id)
        LOGGER.debug("Transceiver parameters table data: {}".format(table))
        trx_timeslot_status = table['CH.STATUS']
        if any(trx_timeslot_status):
            return trx_timeslot_status
        raise BscException("CH.STATUS column is empty. Timeslot status data cannot be read.")

    def _get_transceiver_data_table(self, transceiver_parameters):
        """
        Get trasceiver data table from get transceiever parameters command output
        :param transceiver_parameters: result of ZERO:BTS={bts_id},TRX={trx_id}; command execution
        :return: list of lists with table data where first list item contains table headers
        """
        table = re.search(r'(?s)(RTSL.*?)(?=TRANSCEIVER)', transceiver_parameters)
        try:
            table = table.group(0).splitlines()
        except AttributeError:
            raise BscException("Invalid output. CH.STATUS data cannot be read")
        table = self._remove_header_splitter_and_empty_row(table)
        return table

    @staticmethod
    def _remove_header_splitter_and_empty_row(table):
        table = [row.split() for row in table]
        table.pop(1)
        table.pop(-1)
        return table

    def parse_trx_timeslot_status(self, bts_id, trx_id, expected_timeslot_value, number_of_occurrences,
                                  allow_negative_result=False):
        """
        Parse output from get transciever parameters command (see: ``Get Trx Timeslot Status``) against number
        of expected timeslot value.


        **Input parameters:**

        +---------------------------+------+--------------------------------------------------+
        | Parameter name            | Man. | Description                                      |
        +===========================+======+==================================================+
        | bts_id                    | Yes  | bts/segment identification (string)              |
        +---------------------------+------+--------------------------------------------------+
        | trx_id                    | Yes  | trx identification (string)                      |
        +---------------------------+------+--------------------------------------------------+
        | expected_timeslot_value   | Yes  | expected timeslot value (string)                 |
        +---------------------------+------+--------------------------------------------------+
        | number_of_occurrences     | Yes  | number of occurrences of expected timeslot value |
        +---------------------------+------+--------------------------------------------------+
        | allow_negative_result     | No   | rue/False (boolean), default: False              |
        +---------------------------+------+--------------------------------------------------+


        | **Return value:**
        | ``True`` if  ``number_of_occurrences`` of ``expected_timeslot_value`` is equal or greater than defined,
        | Fail with ``AssertionError`` if ``number_of_occurrences`` of ``expected_timeslot_value`` is lower than defined
        | and ``allow_negative_result`` is set to ``False``, or return ``False`` for ``allow_negative_result`` set to `
        | `True``, Fail with ``BscException`` in case of empty CH.STATUS column


        **Examples:**

        .. code-block:: robotframework

             Parse Trxs Timeslot Status    666    6    ID    3
             Parse Trxs Timeslot Status    666    6    ID    3    allow_negative_result=${True}
        """
        trxs_timeslot_status = self.get_trx_timeslot_status(bts_id, trx_id)
        ts_val_counter = trxs_timeslot_status.count(expected_timeslot_value)
        LOGGER.debug('Trx timeslot status counter: {counter}, expected number of occurences {expected}'.format(
            counter=ts_val_counter, expected=number_of_occurrences))
        if ts_val_counter < int(number_of_occurrences):
            if not allow_negative_result:
                raise AssertionError('Timeslot value counter is lower than expected {counter}<{expected}'.format(
                    counter=ts_val_counter, expected=number_of_occurrences))
            return False
        return True

    def get_sectors_ids(self, bcf_id, alias=True):
        """
        Get sectors IDs from output radio network configuration command.


        **Input parameters:**

        +------------------+------+---------------------------------------+
        | Parameter name   | Man. | Description                           |
        +==================+======+=======================================+
        | bcf_id           | Yes  | BCF ID                                |
        +------------------+------+---------------------------------------+
        | alias            | No   | boolean flag if BTS alias is required |
        +------------------+------+---------------------------------------+


        | **Return value:**
        | list of ids with or without BTS alias. Default option is with an alias.
        | Example with alias     ``['BTS-0151', 'BTS-0152', 'BTS-0153']``
        | Example without alias  ``['151', '152', '153']``


        **Examples:**

        .. code-block:: robotframework

             ${sectors with alias}     Get Sectors Ids    15
             ${sectors without alias}  Get Sectors Ids    bcf_id=15    alias=${False}
        """
        rnc_out = self.output_radio_network_configuration(bcf_id)
        if alias:
            btss_list = re.findall(r'\bBTS\b-\d+', rnc_out)
        else:
            btss_list = re.findall(r'\bBTS\b-0*(\d+)', rnc_out)
        btss_list = [six.text_type(bts) for bts in btss_list]
        return btss_list

    def get_gsm_cells_ids(self, bcf_id):
        """
        Get cell IDs from output radio network configuration command.


        **Input parameters:**

        +------------------+------+-----------------------------+
        | Parameter name   | Man. | Description                 |
        +==================+======+=============================+
        | bcf_id           | Yes  | BCF ID                      |
        +------------------+------+-----------------------------+


        | **Return value:**
        | list of cell ids.
        """
        rnc_out = self.output_radio_network_configuration(bcf_id)
        cell_ids = re.findall(r'\d+\s(\d+)\sBTS\b-0*\d+', rnc_out)
        return [six.text_type(cell_id) for cell_id in cell_ids]

    def get_trxs_list_by_bts_id(self, bts_id, alias=True):
        """
        Get a list of TRXs for given BTS.


        **Input parameters:**

        +------------------+------+---------------------------------------+
        | Parameter name   | Man. | Description                           |
        +==================+======+=======================================+
        | bts_id           | Yes  | BTS ID                                |
        +------------------+------+---------------------------------------+
        | alias            | No   | boolean flag if TRX alias is required |
        +------------------+------+---------------------------------------+


        | **Return value:**
        | list of TRXs for given BTS. Default option is with an alias.
        | - with alias     ``['TRX-001', 'TRX-002', 'TRX-003']``
        | - without alias  ``['1', '2', '3']``
        """
        bsc_out = self._write_and_expect_result('ZEEI:BTS={};'.format(bts_id), 'COMMAND EXECUTED')
        if alias:
            trxs_list = re.findall(r'\bTRX-\d+', bsc_out)
        else:
            trxs_list = re.findall(r'\bTRX-0*(\d+)', bsc_out)
        trxs_list = [six.text_type(trx) for trx in trxs_list]
        return trxs_list

    def get_trxs_states_by_bts_id(self, bts_id, state):
        """
        Read TRXs operational or administrative states for given BTS.


        **Input parameters:**

        +------------------+------+--------------------------+
        | Parameter name   | Man. | Description              |
        +==================+======+==========================+
        | bts_id           | Yes  | sector id                |
        +------------------+------+--------------------------+
        | state            | Yes  | state to get             |
        +------------------+------+--------------------------+


        | **Return value:**
        | list of tuples with TRXs IDs and states.
        | - with alias     ``['TRX-001', 'TRX-002', 'TRX-003']``
        | - without alias  ``['1', '2', '3']``


        **Examples:**

        .. code-block:: robotframework

             ${operational}     Get TRXs States By BTS ID    1271    operational
             ${administrative}  Get TRXs States By BTS ID    1271    administrative
        """
        bsc_out = self._write_and_expect_result('ZEEI:BTS={};'.format(bts_id), 'COMMAND EXECUTED')
        state_regex = {'operational': r'(TRX-\d+)\s+[\w+]\s+([A-Z-]+)', 'administrative': r'(TRX-\d+)\s+([A-Z-]+)'}
        state = state.strip().lower()
        trxs_states = []
        if is_valid_argument(state, ['operational', 'administrative']):
            pattern = state_regex[state]
            trxs_states = re.findall(pattern, bsc_out)
        log_states(trxs_states, state)
        return trxs_states

    def get_om_link_name(self, bcf_id):
        """
        Read O&M link name for given BCF and return it.

        .. note::
            KW was tested on BSC_TAMPERE, BSC_Leopard, BSC_mcBSC32
            if you use it on another BSC in another location it may not work properly.
            It depends on naming convention.


        **Input parameters:**

        +------------------+------+--------------------------+
        | Parameter name   | Man. | Description              |
        +==================+======+==========================+
        | bcf_id           | Yes  | BCF ID                   |
        +------------------+------+--------------------------+


        | **Return value:**
        | O&M link name
        """
        bsc_out = self._write_and_expect_result('ZEEI:BCF={};'.format(bcf_id), 'COMMAND EXECUTED')
        link_name_regex = r'BCF-.*(O.*?)(WO|BL)'
        link_name = re.search(link_name_regex, bsc_out)
        return link_name.group(1).strip()

    def get_om_link_state(self, bcf_id):
        """
        Read O&M link state for given BCF and returns it.


        .. note::
            KW was tested on BSC_TAMPERE, BSC_Leopard, BSC_mcBSC32
            if you use it on another BSC in another location it may not work properly.
            It depends on naming convention.


        **Input parameters:**

        +------------------+------+--------------------------+
        | Parameter name   | Man. | Description              |
        +==================+======+==========================+
        | bcf_id           | Yes  | BCF ID                   |
        +------------------+------+--------------------------+


        | **Return value:**
        | O&M link state
        """
        bsc_out = self._write_and_expect_result('ZEEI:BCF={};'.format(bcf_id), 'COMMAND EXECUTED')
        link_state_regex = r'BCF-.*O.*?(WO|BL)'
        link_state = re.search(link_state_regex, bsc_out)
        return link_state.group(1)

