    def _get_next_sector(self, bcf_id, alias=False):
        """Create generator object with sectors IDs"""
        for sector in self.get_sectors_ids(bcf_id, alias):
            yield sector

    def _get_next_trx(self, bcf_id, alias=False):
        """Create generator object with trxs IDs"""
        for trx_id in self.get_trxs_ids(bcf_id, alias):
            yield trx_id

    def _map_trxs_to_sectors(self, bcf_id, alias=False):
        """Map Trxs to Sectors and return dictionary with dependencies"""
        bts_trx_dict = OrderedDict()
        rnc_out = self.output_radio_network_configuration(bcf_id).splitlines()
        trxs_ids = self._get_next_trx(bcf_id, alias)
        btss_ids = self._get_next_sector(bcf_id, alias)
        bts_id = ''
        for line in rnc_out:
            if 'TRX-' in line:
                trx_id = next(trxs_ids)
                bts_trx_dict[bts_id].append(trx_id)
            elif ' BTS-' in line:
                bts_id = next(btss_ids)
                bts_trx_dict[bts_id] = []
            elif 'COMMAND EXECUTED' in line:
                break
        return bts_trx_dict

    def parse_bcf_active_alarms(self, bcf_id, expected_alarms, ignored_alarms, critical_alarms=[],
                                path_to_file=False):
        # TODO check usages, replace amount key with quantity or repetitions
        """
        Parse output from ``ZEOL:bcf_id;`` command and look for expected and critical (RFS feature) alarms.


        Expected, ignored, and critical alarms should be defined as a list of dictionaries.
        Only keys described listed here are allowed:

        * number - alarm number (string)
        * fault - alarm fault (string)
        * text - alarm text (string)
        * source - objects for which alarm is raised (list of strings)
        * program_block - alarm program block (string)
        * amount - number of alarm repetitions (integer or string)


        Any other key will cause ``KeyError`` and Fail keyword execution.
        There is no need to define all above mentioned keys. Keys that aren't defined won't be checked.

        If the number of alarm repetitions isn't defined, all alarms which match rest of defined keys will be treated
        as expected. If alarm amount is defined, then all excessive alarms matching the pattern will be treated
        as unexpected whereas those with insufficient number of occurrences will be treated as missing.

        Example for list of dictionaries structure:

        .. code-block:: python

            list_of_expected_alarms = [{'number': '52082', 'fault': '7738', 'text': 'BTS WITH NO TRANSACTIONS',
                                        'source: ['BCF-0015', 'BTS-0152'], 'program_block': 'QUAL',
                                        'amount': '1'}, {...}, {...}]

            list_of_ignored_alarms = [{'number': '50084', 'fault': '7801', 'text': 'MMI CONNECTED TO BASE STATION',
                                        'source: ['BCF-0015'], 'program_block': 'ENVIR', 'amount': '1'}, {...}, {...}]


        **Input parameters:**

        +------------------+------+----------------------------------------------+
        | Parameter name   | Man. | Description                                  |
        +==================+======+==============================================+
        | bcf_id           | Yes  | BCF id                                       |
        +------------------+------+----------------------------------------------+
        | expected_alarms  | Yes  | list of expected alarms                      |
        +------------------+------+----------------------------------------------+
        | ignored_alarms   | Yes  | list of alarms which should be ignored       |
        +------------------+------+----------------------------------------------+
        | critical_alarms  | No   | list of alarms which are treated as critical |
        +------------------+------+----------------------------------------------+
        | path_to_file     | No   | path to file where alarms will be stored     |
        +------------------+------+----------------------------------------------+


        | **Return value:**
        | Expected, missing, unexpected, critical alarms lists
        | If some group is not found, then respective list is empty.


        **Examples:**

        .. code-block:: robotframework

            ${active alarms}  Parse Bcf Active Alarms     15    ${expected alarms list}    ${ignored alarms list}
            ${critical alarms list}
        """
        output = self.get_bcf_active_alarms(bcf_id)
        bsc_parser = Parser(output)
        return bsc_parser.analyze_bcf_active_alarms(expected_alarms, ignored_alarms, critical_alarms, path_to_file,
                                                    bsc_name=self.bsc_name)

    def parse_bcf_alarms_history(self, bcf_id, expected_alarms, ignored_alarms, critical_alarms=[],
                                 time_start=False, time_end=False, path_to_file=False):
        """
        Parse output from ``ZEOH::BCF=bcf_id;`` command and look for expected alarms in given time range.


        time_start and time_end should be defined in a format ``HH:MM:SS``. These parameters describe time range in
        which BCF alarms history will be parsed.

        Expected, ignored, and critical alarms should be defined as a list of dictionaries.
        Only keys described below should be defined for alarms dictionaries in a list:

        * number - alarm number (string)
        * fault - alarm fault (string)
        * text - alarm text (string)
        * source - objects for which alarm is raised (list of strings)
        * program_block - alarm program block (string)
        * amount - number of alarm repetitions (integer or string)

        Any other key will cause KeyError and Fail keyword execution.
        There is no need to define all abovementioned keys. Keys that aren't defined won't be checked.

        If a number of alarm repetitions isn't defined, all alarms which match the rest of defined keys will be treated
        as expected. If alarm amount is defined then all excessive alarms matching pattern will be treated
        as unexpected, and those with insufficient number of occurrences will be treated as missing.

        Example of a list of dictionaries structure:

        .. code-block:: python

            list_of_expected_alarms = [{'number': '52082', 'fault': '7738', 'text': 'BTS WITH NO TRANSACTIONS',
                                        'source: ['BCF-0015', 'BTS-0152'], 'program_block': 'QUAL',
                                        'amount': '1'}, {...}, {...}]

            list_of_ignored_alarms = [{'number': '50084', 'fault': '7801', 'text': 'MMI CONNECTED TO BASE STATION',
                                        'source: ['BCF-0015'], 'program_block': 'ENVIR', 'amount': '1'}, {...}, {...}]


        **Input parameters:**

        +------------------+------+-----------------------------------------------------------------------------------+
        | Parameter name   | Man. | Description                                                                       |
        +==================+======+===================================================================================+
        | bcf_id           | Yes  | BCF id                                                                            |
        +------------------+------+-----------------------------------------------------------------------------------+
        | expected_alarms  | Yes  | list of expected alarms                                                           |
        +------------------+------+-----------------------------------------------------------------------------------+
        | ignored_alarms   | Yes  | list of alarms which should be ignored                                            |
        +------------------+------+-----------------------------------------------------------------------------------+
        | critical_alarms  | No   | list of alarms which are treated as critical                                      |
        +------------------+------+-----------------------------------------------------------------------------------+
        | time_start       | No   | time in format HH:MM:SS defines the beginning of the time span of alarms analysis |
        +------------------+------+-----------------------------------------------------------------------------------+
        | time_end         | No   | time in format HH:MM:SS defines the end of the time span of alarms analysis       |
        +------------------+------+-----------------------------------------------------------------------------------+
        | path_to_file     | No   | path to file where alarms will be stored                                          |
        +------------------+------+-----------------------------------------------------------------------------------+


        | **Return value:**
        | Expected, missing, unexpected, critical alarms lists
        | If some group is not found, then respective list is empty.


        **Example:**

        .. code-block:: robotframework

            ${history alarms}  Parse Bcf Alarms History  15  ${expected alarms}  ${ignored alarms}  ${critical alarms}
            10:00:00  11:00:00
        """
        output = self.get_bcf_alarms_history(bcf_id)
        bsc_parser = Parser(output)
        return bsc_parser.analyze_bcf_alarms_history(expected_alarms, ignored_alarms, critical_alarms, time_start,
                                                     time_end, path_to_file, bsc_name=self.bsc_name)

