    def reset(self, bcf_id, no_of_tries=3, timeout='20', allow_negative_result=False):  # noqa: C901
        """
        Reset BCF with ``ZEFR:bcf_id;`` command.


        **Input parameters:**

        +-------------------------+------+-----------------------------------------------------+
        | Parameter name          | Man. | Description                                         |
        +=========================+======+=====================================================+
        | bcf_id                  | Yes  | BCF id                                              |
        +-------------------------+------+-----------------------------------------------------+
        | no_of_tries             | No   | number of reset attempts                            |
        +-------------------------+------+-----------------------------------------------------+
        | timeout                 | No   | timeout for a single reset attempt                  |
        +-------------------------+------+-----------------------------------------------------+
        | allow_negative_result   | No   | boolean flag which allows mismatch in states values |
        +-------------------------+------+-----------------------------------------------------+


        | **Return value:**
        | ``True`` if BSC return status is 'BTS SITE RESET STARTED', otherwise fail with ``ResetAborted`` exception
        | ``False`` if reset wasn't performed within defined number of tries and ``allow_negative_result`` was set to
        | ``True``.


        **Examples:**

        .. code-block:: robotframework

             ${reset status}    Reset    15
             ${reset status}    Reset    15    allow_negative_result=${True}
        """
        expected = 'BTS SITE RESET STARTED'
        no_of_tries = int(no_of_tries)
        default_time = self.set_timeout(timeout)
        for attempt in range(no_of_tries):
            try:
                self._write_and_expect_result('ZEFR:{};'.format(bcf_id), 'CONFIRM COMMAND EXECUTION: Y/N ?')
                self.cache.current_conn.write('Y\r')
                output = self.read_until(expected)
                if expected not in output:
                    raise NoMatchError("{} wasn't return by BSC")
                break
            except Exception as exc:
                LOGGER.debug('Reset operation failed in try {}. Reason: {}'.format(attempt, exc))
                if attempt == no_of_tries - 1:
                    if not allow_negative_result:
                        raise ResetAborted('Reset cannot be performed: {}'.format(exc))
                    else:
                        return False
            finally:
                time.sleep(5)
                self.cache.current_conn.read_very_eager()
                self.set_timeout(default_time)
        return True

    def lock_trx(self, bts_id, trx_id, timeout='7 min', retry_interval='5'):
        """
        Lock given trx on a given sector id.


        **Input parameters:**

        +-----------------+------+------------------------+
        | Parameter name  | Man. | Description            |
        +=================+======+========================+
        | bts_id          | Yes  | BTS id                 |
        +-----------------+------+------------------------+
        | trx_id          | Yes  | TRX id                 |
        +-----------------+------+------------------------+
        | timeout         | No   | lock operation timeout |
        +-----------------+------+------------------------+
        | retry_interval  | No   | retry interval         |
        +-----------------+------+------------------------+


        | **Return value:**
        | True if TRX was locked successfully, otherwise fail with TrxsLockFail exception or error returned by BSC


        **Examples:**

        .. code-block:: robotframework

            ${lock status}    Lock TRX    251    1

        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        max_time = time.time() + timeout
        while True:
            try:
                rnc_out = self._write_and_expect_result('ZERS:BTS={},TRX={}:L:;'.format(bts_id, trx_id), ' LOCKED',
                                                        10, IncorrectState, additional_expected_result='COMMAND EXECUTED')
                self.cache.current_conn.read_until('COMMAND EXECUTED', 2)
                break
            except NoMatchError:
                raise TrxsLockFail('Trx {} cannot be locked on sector {}'.format(trx_id, bts_id))
            except (LackOfResources, Exception):
                if time.time() > max_time:
                    raise
                time.sleep(retry_interval)
        return rnc_out

    def lock_all_trxs_on_bts(self, bts_id, timeout='30', retry_interval='30', allow_negative_result=False):  # noqa: C901
        """
        Lock all TRXs on given BTS.

        ``timeout`` parameter is timeout of operation on a single TRX not for all TRXs
        (i.e., if ``timeout=30``, then total KW's operation timeout is equal to timeout*number of TRXs).


        **Input parameters:**

        +-------------------------+------+--------------------------------------------+
        | Parameter name          | Man. | Description                                |
        +=========================+======+============================================+
        | bts_id                  | Yes  | BTS id                                     |
        +-------------------------+------+--------------------------------------------+
        | timeout                 | No   | lock operation timeout                     |
        +-------------------------+------+--------------------------------------------+
        | retry_interval          | No   | retry interval                             |
        +-------------------------+------+--------------------------------------------+
        | allow_negative_result   | No   | boolean flag for operation negative result |
        +-------------------------+------+--------------------------------------------+


        | **Return value:**
        | - True if all TRXs get locked otherwise raise ``TrxsLockFail`` exception
        | - False if some TRX aren't locked but ``allow_negative_result`` is set to ``True``.
        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        trxs = self.get_trxs_list_by_bts_id(bts_id, alias=False)
        for trx in trxs:
            max_time = time.time() + timeout
            while True:
                try:
                    locked = self.lock_trx(bts_id, trx)
                    if locked:
                        break
                except TrxsLockFail:
                    if time.time() > max_time:
                        if allow_negative_result:
                            return False
                        else:
                            raise
                    time.sleep(retry_interval)
        return True

    def lock_all_trxs(self, bcf_id, timeout='30', retry_interval='30', allow_negative_result=False):  # noqa: C901
        """
        Lock all TRXs on provided BCF.


        .. note::
            ``timeout`` parameter is a timeout of operation on a single TRX, not for all TRXs
            (i.e., if ``timeout=200``, then total KW's operation timeout is equal to timeout*number of TRXs).


        **Input parameters:**

        +-------------------------+------+--------------------------------------------+
        | Parameter name          | Man. | Description                                |
        +=========================+======+============================================+
        | bcf_id                  | Yes  | BCF id                                     |
        +-------------------------+------+--------------------------------------------+
        | timeout                 | No   | lock operation timeout                     |
        +-------------------------+------+--------------------------------------------+
        | retry_interval          | No   | retry interval                             |
        +-------------------------+------+--------------------------------------------+
        | allow_negative_result   | No   | boolean flag for operation negative result |
        +-------------------------+------+--------------------------------------------+


        | **Return value:**
        | - ``True`` if all TRXs get locked, otherwise fail with ``TrxsLockFail`` exception or error returned by BSC
        | - ``False`` if some TRX aren't locked but ``allow_negative_result`` is set to ``True``.
        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        bts_trx_dict = self._map_trxs_to_sectors(bcf_id, False)
        sectors = bts_trx_dict.keys()
        for sector in sectors:
            trxs = bts_trx_dict.get(sector)
            for trx in trxs:
                max_time = time.time() + timeout
                while True:
                    try:
                        locked = self.lock_trx(sector, trx)
                        if locked:
                            break
                    except TrxsLockFail:
                        if time.time() > max_time:
                            if allow_negative_result:
                                return False
                            else:
                                raise
                        time.sleep(retry_interval)
                        continue
        return True

    def unlock_trx(self, bts_id, trx_id, timeout='10', retry_interval='5'):
        """
        Unlock given trx on provided sector id.


        **Input parameters:**

        +-------------------------+------+--------------------------------------------+
        | Parameter name          | Man. | Description                                |
        +=========================+======+============================================+
        | bts_id                  | Yes  | BTS id                                     |
        +-------------------------+------+--------------------------------------------+
        | trx_id                  | Yes  | TRX id                                     |
        +-------------------------+------+--------------------------------------------+
        | timeout                 | No   | lock operation timeout                     |
        +-------------------------+------+--------------------------------------------+
        | retry_interval          | No   | retry interval                             |
        +-------------------------+------+--------------------------------------------+


        | **Return value:**
        | True if TRX was unlocked successfully, otherwise fail with ``TrxsUnlockFail`` exception or error returned by
        | BSC


        **Examples:**

        .. code-block:: robotframework

            ${unlock status}    Unlock TRX    251    1
        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        max_time = time.time() + timeout
        while True:
            try:
                rnc_out = self._write_and_expect_result('ZERS:BTS={},TRX={}:U:;'.format(bts_id, trx_id), 'UNLOCKED',
                                                        10, IncorrectState, TypeError,
                                                        additional_expected_result='COMMAND EXECUTED')
                break
            except NoMatchError:
                raise TrxsUnlockFail('Trx {} cannot be unlocked on sector {}'.format(trx_id, bts_id))
            except (LackOfResources, Exception):
                if time.time() > max_time:
                    raise
                time.sleep(retry_interval)
        return rnc_out

    def unlock_all_trxs_on_bts(self, bts_id, timeout='200', retry_interval='30', allow_negative_result=False):  # noqa: C901
        """
        Unlock all TRXs on given BTS.

        .. note::
            ``timeout parameter`` is timeout of operation on single TRX not for all TRXs,
            (i.e., if ``timeout=200``, then total KW's operation timeout is equal to ``timeout`` * number of TRXs).


        **Input parameters:**

        +-------------------------+------+--------------------------------------------+
        | Parameter name          | Man. | Description                                |
        +=========================+======+============================================+
        | bts_id                  | Yes  | BTS id                                     |
        +-------------------------+------+--------------------------------------------+
        | timeout                 | No   | lock operation timeout                     |
        +-------------------------+------+--------------------------------------------+
        | retry_interval          | No   | retry interval                             |
        +-------------------------+------+--------------------------------------------+
        | allow_negative_result   | No   | boolean flag for operation negative result |
        +-------------------------+------+--------------------------------------------+


        | **Return value:**
        | - ``True`` if all TRXs get unlocked otherwise raise ``TrxsUnlockFail`` exception
        | - ``False`` if some TRX aren't unlocked but ``allow_negative_result`` is set to ``True``.


        **Examples:**

        .. code-block:: robotframework

            ${unlock status}  Unlock TRXs On BTS  1271
        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        trxs = self.get_trxs_list_by_bts_id(bts_id, alias=False)
        for trx in trxs:
            max_time = time.time() + timeout
            while True:
                try:
                    self.unlock_trx(bts_id, trx)
                    break
                except (TrxsUnlockFail, Exception):
                    if time.time() > max_time:
                        if allow_negative_result:
                            return False
                        else:
                            raise
                    time.sleep(retry_interval)
        return True

