    def lock_sector(self, sector_id, timeout='7 min', retry_interval='5 sec'):
        """
        Lock sector with given id.


        .. note::
            Lock/Unlock operation may take up to 7 minutes (it is related to BSC SW).


        **Input parameters:**

        +-----------------+------+------------------------+
        | Parameter name  | Man. | Description            |
        +=================+======+========================+
        | sector_id       | Yes  | sector id              |
        +-----------------+------+------------------------+
        | timeout         | No   | lock operation timeout |
        +-----------------+------+------------------------+
        | retry_interval  | No   | retry interval         |
        +-----------------+------+------------------------+


        | **Return value:**
        | - ``True`` if sector get locked, otherwise fail with ``SectorLockFail`` exception or error returned by BSC


        **Examples:**

        .. code-block:: robotframework

            ${lock status}    Lock Sector    251
        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        max_time = time.time() + timeout
        while True:
            try:
                rnc_out = self._write_and_expect_result('ZEQS:BTS={}:L:;'.format(sector_id), ' LOCKED', 10,
                                                        IncorrectState, TypeError,
                                                        additional_expected_result='COMMAND EXECUTED')
                break
            except NoMatchError:
                raise SectorLockFail('Sector {} cannot be locked'.format(sector_id))
            except (LackOfResources, Exception):
                if time.time() > max_time:
                    raise
                time.sleep(retry_interval)
        return rnc_out

