    def _change_base_control_function_administrative_state(self, bcf_id, state):
        """
        Change administrative state of BCF (lock/unlock operation).
        Return output from ``ZEFS:bcf_id:state;`` command when it passes.
        Fail with BSC error if some exception is raised.
        """
        state = state.upper()
        is_valid_argument(state, ['L', 'U', 'LOCK', 'UNLOCK'])
        expect = ""
        if state == 'LOCK' or state == 'L':
            state = 'L'
            expect = " LOCKED"
        elif state == 'UNLOCK' or state == 'U':
            state = 'U'
            expect = "UNLOCKED"
        return self._write_and_expect_result('ZEFS:{}:{};'.format(bcf_id, state), expect, None,
                                             IncorrectState, TypeError,
                                             additional_expected_result='COMMAND EXECUTED')

    def delete_sector(self, sector_id, timeout='10'):
        """
        Delete sector with a given ID.


        .. note::
            Sector should be locked before deletion. See ``Lock Sector`` keyword. Otherwise this keyword will rise
            ``IncorrectState`` exception.


        **Input parameters:**

        +-----------------+------+------------------------+
        | Parameter name  | Man. | Description            |
        +=================+======+========================+
        | sector_id       | Yes  | sector id              |
        +-----------------+------+------------------------+
        | timeout         | No   | lock operation timeout |
        +-----------------+------+------------------------+


        | **Return value:**
        | - bsc output if operation succeeds, otherwise raise ``SectorRemoveFail`` or BSC error if BSC returns one
        """
        timeout = timestr_to_secs(timeout)
        expected_status = 'COMMAND EXECUTED'
        try:
            self._write_and_expect_result('ZEQD:BTS={};'.format(sector_id), 'CONFIRM COMMAND EXECUTION: Y/N ?')
            self.cache.current_conn.write('Y\r')
            deletion_status = self.cache.current_conn.read_until(expected_status, timeout)
            self._check_output(expected_status, deletion_status)
        except IncorrectState:
            raise
        except (NoMatchError, Exception) as e:
            raise SectorRemoveFail('Sector cannot be delete. Error: {}'.format(e))
        return deletion_status

    def delete_all_sectors(self, bcf_id, timeout='30 min', retry_interval='30', allow_negative_result=False):  # noqa: C901
        """
        Delete all Sectors on given BCF.


        .. note::
            ``timeout`` parameter is timeout of operation on single Sector not for all Sectors,
            so full operation timeout is equal to ``timeout`` * number of Sectors.


        .. note::
            Sector should be locked before deletion. See ``Lock Sector`` or ``Lock All Sectors`` keywords.
            Otherwise this keyword will rise ``IncorrectState`` exception and will break keyword execution irrespective
            of timeout.


        **Input parameters:**

        +-------------------------+------+------------------------+
        | Parameter name          | Man. | Description            |
        +=========================+======+========================+
        | bcf_id                  | Yes  | BCF id                 |
        +-------------------------+------+------------------------+
        | timeout                 | No   | lock operation timeout |
        +-------------------------+------+------------------------+
        | retry_interval          | No   | retry interval         |
        +-------------------------+------+------------------------+
        | allow_negative_result   | No   |                        |
        +-------------------------+------+------------------------+


        | **Return value:**
        | - bsc output if operation succeed, otherwise raise ``SectorRemoveFail`` or BSC error if BSC returns one
        | - ``False`` if action fail but ``allow_negative_result`` is set to ``True``.


        **Examples:**

        .. code-block:: robotframework

            ${delete status}    Delete All Sectors    15
        """
        timeout = timestr_to_secs(timeout)
        retry_interval = timestr_to_secs(retry_interval)
        for sector in self.get_sectors_ids(bcf_id, False):
            max_time = time.time() + timeout
            while True:
                try:
                    self.delete_sector(sector)
                    break
                except IncorrectState:
                    raise
                except SectorRemoveFail:
                    if time.time() > max_time:
                        if allow_negative_result:
                            return False
                        else:
                            raise
                    time.sleep(retry_interval)
        return True
